func TestItLibSuiteFootnotes_footnotes_test_20(t *testing.T) {
	original := "* First\n" +
		"  [^1]: test\n" +
		"* Second [^1] test\n" +
		"\n" +
		"\n" +
		"> first\n" +
		"> [^2]: test\n" +
		"> Second [^2] test\n" +
		"\n" +
		"\n" +
		"   First   | Second\n" +
		"-----------|----------\n" +
		"first      | second\n" +
		"[^3]: test | test [^3]\n" +
		"\n" +
		"\n" +
		"|    First   | Second    |\n" +
		"|------------|-----------|\n" +
		"| first      | second    |\n" +
		"| [^4]: test | test [^4] |\n" +
		"\n" +
		"> [^5]: * test [^5]\n"
	expected := "<ul>\n" +
		"<li>First\n" +
		"<div class=\"footnote-definition\" id=\"1\"><sup class=\"footnote-definition-label\">1</sup>\n" +
		"<p>test</p>\n" +
		"</div>\n" +
		"</li>\n" +
		"<li>Second <sup class=\"footnote-reference\"><a href=\"#1\">1</a></sup> test</li>\n" +
		"</ul>\n" +
		"<blockquote>\n" +
		"<p>first</p>\n" +
		"<div class=\"footnote-definition\" id=\"2\"><sup class=\"footnote-definition-label\">2</sup>\n" +
		"<p>test\n" +
		"Second <sup class=\"footnote-reference\"><a href=\"#2\">2</a></sup> test</p>\n" +
		"</div>\n" +
		"</blockquote>\n" +
		"<table><thead><tr><th>First</th><th>Second</th></tr></thead><tbody>\n" +
		"<tr><td>first</td><td>second</td></tr>\n" +
		"</tbody></table>\n" +
		"<div class=\"footnote-definition\" id=\"3\"><sup class=\"footnote-definition-label\">3</sup>\n" +
		"<p>test | test <sup class=\"footnote-reference\"><a href=\"#3\">3</a></sup></p>\n" +
		"</div>\n" +
		"<table><thead><tr><th>First</th><th>Second</th></tr></thead><tbody>\n" +
		"<tr><td>first</td><td>second</td></tr>\n" +
		"<tr><td>[^4]: test</td><td>test [^4]</td></tr>\n" +
		"</tbody></table>\n" +
		"<blockquote>\n" +
		"<div class=\"footnote-definition\" id=\"5\"><sup class=\"footnote-definition-label\">4</sup>\n" +
		"<ul>\n" +
		"<li>test <sup class=\"footnote-reference\"><a href=\"#5\">4</a></sup></li>\n" +
		"</ul>\n" +
		"</div>\n" +
		"</blockquote>\n"

	testMarkdownHtml(t, original, expected, false, false, false)
}

