func TestItLibSuiteFootnotes_footnotes_test_22(t *testing.T) {
	original := "[^foo\\\n" +
		"bar]: not a footnote definition\n" +
		"\n" +
		"[baz\\\n" +
		"quux]: https://rust-lang.org\n" +
		"\n" +
		"[first\n" +
		"second]: https://rust-lang.org\n" +
		"\n" +
		"[^third\n" +
		"fourth]: not a footnote definition\n" +
		"\n" +
		"[baz\\\n" +
		"quux]\n" +
		"[^foo\\\n" +
		"bar]\n" +
		"[first\n" +
		"second]\n" +
		"[^third\n" +
		"fourth]\n"
	expected := "<p>[^foo<br>\n" +
		"bar]: not a footnote definition</p>\n" +
		"<p>[^third\n" +
		"fourth]: not a footnote definition</p>\n" +
		"<p><a href=\"https://rust-lang.org\">baz<br>\n" +
		"quux</a>\n" +
		"[^foo<br>\n" +
		"bar]\n" +
		"<a href=\"https://rust-lang.org\">first\n" +
		"second</a>\n" +
		"[^third\n" +
		"fourth]</p>\n"

	testMarkdownHtml(t, original, expected, false, false, false)
}

